import type { JsonRpcRequest } from "./types.js";
import { makeContext, makeRequest } from "./protocol.js";
import { replayFixture, serveStdio } from "./transport.js";
import { TOOL_DESCRIPTORS, makeExecutors, makeIncidents } from "./tools.js";

function demoFixture(): JsonRpcRequest[] {
  return [
    makeRequest(1, "server/discover"),
    makeRequest(2, "tools/list"),
    makeRequest(3, "tools/call", {
      name: "incidents_list",
      arguments: { severity: "p0" },
    }),
    makeRequest(4, "tools/call", {
      name: "incidents_get",
      arguments: { id: "INC-101" },
    }),
    makeRequest(5, "tools/call", {
      name: "incidents_ack",
      arguments: { id: "INC-101" },
    }),
    makeRequest(6, "tools/call", {
      name: "incidents_get",
      arguments: { id: "INC-101" },
    }),
    makeRequest(7, "tools/call", { name: "no_such_tool", arguments: {} }),
    makeRequest(8, "tools/list", {}, "2027-01-01"),
  ];
}

function runDemo(): void {
  const context = makeContext(TOOL_DESCRIPTORS, makeExecutors(makeIncidents()));

  process.stdout.write("=".repeat(72) + "\n");
  process.stdout.write("PHASE 19 LESSON 13 - stateless MCP server (TypeScript, no SDK)\n");
  process.stdout.write("=".repeat(72) + "\n");

  const messages = demoFixture();
  const replies = replayFixture(context, messages);
  for (let i = 0; i < messages.length; i += 1) {
    const req = messages[i];
    const rep = replies[i];
    if (!req || !rep) continue;
    process.stdout.write("\n>>> " + JSON.stringify(req) + "\n");
    process.stdout.write("<<< " + JSON.stringify(rep) + "\n");
  }
}

function main(): void {
  if (process.argv.includes("--serve")) {
    const context = makeContext(TOOL_DESCRIPTORS, makeExecutors(makeIncidents()));
    serveStdio(context);
    return;
  }
  runDemo();
}

main();

import type {
  JsonSchema,
  JsonRpcRequest,
  JsonRpcRequestId,
  JsonRpcResponse,
  ToolArgs,
  ToolDescriptor,
  ToolExecutor,
} from "./types.js";

export const PROTOCOL_VERSION = "2026-07-28";
export const SUPPORTED_VERSIONS = [PROTOCOL_VERSION] as const;
export const PROTOCOL_VERSION_KEY = "io.modelcontextprotocol/protocolVersion";
export const CLIENT_CAPABILITIES_KEY = "io.modelcontextprotocol/clientCapabilities";
export const CLIENT_INFO_KEY = "io.modelcontextprotocol/clientInfo";
export const SERVER_INFO_KEY = "io.modelcontextprotocol/serverInfo";
export const SERVER_NAME = "com.example/internal-incidents";
export const SERVER_INFO = { name: SERVER_NAME, version: "1.0.0" };
export const SERVER_CAPABILITIES = { tools: { listChanged: false } };

export type ServerContext = {
  descriptors: ToolDescriptor[];
  executors: Record<string, ToolExecutor>;
};

export function makeContext(
  descriptors: ToolDescriptor[],
  executors: Record<string, ToolExecutor>,
): ServerContext {
  return { descriptors, executors };
}

class RpcProblem extends Error {
  constructor(
    readonly code: number,
    message: string,
    readonly data?: unknown,
  ) {
    super(message);
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validateSchema(value: unknown, schema: JsonSchema, path: string): string[] {
  if (schema.type === "object") {
    if (!isRecord(value)) return [`${path} must be an object`];
    const issues: string[] = [];
    const properties = schema.properties ?? {};
    for (const required of schema.required ?? []) {
      if (!Object.hasOwn(value, required)) issues.push(`${path}.${required} is required`);
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!Object.hasOwn(properties, key)) issues.push(`${path}.${key} is not allowed`);
      }
    }
    for (const [key, propertySchema] of Object.entries(properties)) {
      if (Object.hasOwn(value, key)) {
        issues.push(...validateSchema(value[key], propertySchema, `${path}.${key}`));
      }
    }
    return issues;
  }
  if (schema.type === "string" && typeof value !== "string") {
    return [`${path} must be a string`];
  }
  if (schema.enum && !schema.enum.includes(value as string)) {
    return [`${path} must be one of ${schema.enum.join(", ")}`];
  }
  return [];
}

export function requestMeta(
  version = PROTOCOL_VERSION,
  clientCapabilities: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    [PROTOCOL_VERSION_KEY]: version,
    [CLIENT_CAPABILITIES_KEY]: clientCapabilities,
    [CLIENT_INFO_KEY]: { name: "lesson-13-demo-client", version: "1.0.0" },
  };
}

export function makeRequest(
  id: JsonRpcRequestId,
  method: string,
  params: Record<string, unknown> = {},
  version = PROTOCOL_VERSION,
): JsonRpcRequest {
  return {
    jsonrpc: "2.0",
    id,
    method,
    params: { ...params, _meta: requestMeta(version) },
  };
}

function complete(
  payload: Record<string, unknown>,
  cache?: { ttlMs: number; cacheScope: "public" | "private" },
): Record<string, unknown> {
  const result: Record<string, unknown> = {
    resultType: "complete",
    ...payload,
    _meta: { [SERVER_INFO_KEY]: { ...SERVER_INFO } },
  };
  if (cache) {
    result.ttlMs = cache.ttlMs;
    result.cacheScope = cache.cacheScope;
  }
  return result;
}

function validateRequest(msg: JsonRpcRequest): Record<string, unknown> {
  if (!isRecord(msg.params)) {
    throw new RpcProblem(-32602, "params must be an object");
  }
  const meta = msg.params._meta;
  if (!isRecord(meta)) {
    throw new RpcProblem(-32602, "params._meta is required");
  }
  const requested = meta[PROTOCOL_VERSION_KEY];
  if (typeof requested !== "string") {
    throw new RpcProblem(-32602, `${PROTOCOL_VERSION_KEY} is required`);
  }
  if (!(SUPPORTED_VERSIONS as readonly string[]).includes(requested)) {
    throw new RpcProblem(-32022, "Unsupported protocol version", {
      supported: [...SUPPORTED_VERSIONS],
      requested,
    });
  }
  if (!isRecord(meta[CLIENT_CAPABILITIES_KEY])) {
    throw new RpcProblem(-32602, `${CLIENT_CAPABILITIES_KEY} is required`);
  }
  const clientInfo = meta[CLIENT_INFO_KEY];
  if (
    clientInfo !== undefined &&
    (!isRecord(clientInfo) ||
      typeof clientInfo.name !== "string" ||
      typeof clientInfo.version !== "string")
  ) {
    throw new RpcProblem(-32602, `${CLIENT_INFO_KEY} is malformed`);
  }
  return msg.params;
}

function handleDiscover(): Record<string, unknown> {
  return complete(
    {
      supportedVersions: [...SUPPORTED_VERSIONS],
      capabilities: SERVER_CAPABILITIES,
      instructions: "Use incident tools to list, inspect, and acknowledge incidents.",
    },
    { ttlMs: 3_600_000, cacheScope: "public" },
  );
}

function handleToolsList(context: ServerContext): Record<string, unknown> {
  const tools = [...context.descriptors].sort((left, right) =>
    left.name < right.name ? -1 : left.name > right.name ? 1 : 0,
  );
  return complete({ tools }, { ttlMs: 300_000, cacheScope: "public" });
}

function handleToolsCall(
  context: ServerContext,
  params: Record<string, unknown>,
): Record<string, unknown> {
  const name = params.name;
  const rawArgs = params.arguments ?? {};
  if (typeof name !== "string" || !name) {
    throw new RpcProblem(-32602, "tools/call requires a non-empty string name");
  }
  const executor = context.executors[name];
  const descriptor = context.descriptors.find((candidate) => candidate.name === name);
  if (!executor || !descriptor) {
    throw new RpcProblem(-32602, `Unknown tool: ${name}`);
  }
  const schemaIssues = validateSchema(rawArgs, descriptor.inputSchema, "arguments");
  if (schemaIssues.length > 0) {
    return complete({
      content: [
        {
          type: "text",
          text: `Invalid arguments for ${name}: ${schemaIssues.join("; ")}`,
        },
      ],
      isError: true,
    });
  }
  try {
    return complete({ content: executor(rawArgs as ToolArgs), isError: false });
  } catch (err) {
    return complete({ content: [{ type: "text", text: String(err) }], isError: true });
  }
}

function rpcError(
  id: JsonRpcRequestId,
  code: number,
  message: string,
  data?: unknown,
): JsonRpcResponse {
  return {
    jsonrpc: "2.0",
    id,
    error: data === undefined ? { code, message } : { code, message, data },
  };
}

export function dispatch(context: ServerContext, msg: JsonRpcRequest): JsonRpcResponse | null {
  if (msg.id === undefined) return null;
  const id = msg.id;
  try {
    const params = validateRequest(msg);
    if (msg.method === "server/discover") {
      return { jsonrpc: "2.0", id, result: handleDiscover() };
    }
    if (msg.method === "tools/list") {
      return { jsonrpc: "2.0", id, result: handleToolsList(context) };
    }
    if (msg.method === "tools/call") {
      return { jsonrpc: "2.0", id, result: handleToolsCall(context, params) };
    }
    return rpcError(id, -32601, `Method not found: ${msg.method}`);
  } catch (err) {
    if (err instanceof RpcProblem) {
      return rpcError(id, err.code, err.message, err.data);
    }
    return rpcError(id, -32603, "Internal error", { detail: String(err) });
  }
}

export function parseRpc(
  line: string,
): { ok: true; msg: JsonRpcRequest } | { ok: false; err: string; code: number } {
  let raw: unknown;
  try {
    raw = JSON.parse(line);
  } catch (err) {
    return { ok: false, err: String(err), code: -32700 };
  }
  if (!isRecord(raw) || raw.jsonrpc !== "2.0" || typeof raw.method !== "string") {
    return { ok: false, err: "invalid JSON-RPC envelope", code: -32600 };
  }
  if (
    "id" in raw &&
    typeof raw.id !== "string" &&
    typeof raw.id !== "number"
  ) {
    return { ok: false, err: "invalid JSON-RPC envelope", code: -32600 };
  }
  return { ok: true, msg: raw as JsonRpcRequest };
}

import type { ContentBlock, Incident, ToolArgs, ToolDescriptor, ToolExecutor } from "./types.js";

export function makeIncidents(): Record<string, Incident> {
  return {
    "INC-101": { id: "INC-101", severity: "p0", title: "checkout 500s", acked: false },
    "INC-102": { id: "INC-102", severity: "p2", title: "slow dashboard", acked: true },
    "INC-103": { id: "INC-103", severity: "p1", title: "rate-limit storm", acked: false },
  };
}

export const TOOL_DESCRIPTORS: ToolDescriptor[] = [
  {
    name: "incidents_list",
    description:
      "Use when listing recent incidents or filtering by severity. Do not use to look up a single id.",
    inputSchema: {
      type: "object",
      properties: { severity: { type: "string", enum: ["p0", "p1", "p2"] } },
      required: [],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
  },
  {
    name: "incidents_get",
    description: "Use to fetch one incident by id. Do not use for listing.",
    inputSchema: {
      type: "object",
      properties: { id: { type: "string" } },
      required: ["id"],
      additionalProperties: false,
    },
    annotations: { readOnlyHint: true },
  },
  {
    name: "incidents_ack",
    description: "Use to acknowledge an incident. Write op; only authorized callers.",
    inputSchema: {
      type: "object",
      properties: { id: { type: "string" } },
      required: ["id"],
      additionalProperties: false,
    },
    annotations: { destructiveHint: true, readOnlyHint: false },
  },
];

export function makeExecutors(store: Record<string, Incident>): Record<string, ToolExecutor> {
  const execList = (args: ToolArgs): ContentBlock[] => {
    const sev = typeof args.severity === "string" ? args.severity : undefined;
    const items = Object.values(store).filter((i) => !sev || i.severity === sev);
    return [{ type: "text", text: JSON.stringify(items) }];
  };

  const execGet = (args: ToolArgs): ContentBlock[] => {
    const id = String(args.id ?? "");
    const inc = store[id];
    if (!inc) throw new Error(`not found: ${id}`);
    return [{ type: "text", text: JSON.stringify(inc) }];
  };

  const execAck = (args: ToolArgs): ContentBlock[] => {
    const id = String(args.id ?? "");
    const inc = store[id];
    if (!inc) throw new Error(`not found: ${id}`);
    inc.acked = true;
    return [{ type: "text", text: JSON.stringify({ id, acked: true }) }];
  };

  return {
    incidents_list: execList,
    incidents_get: execGet,
    incidents_ack: execAck,
  };
}

import { createInterface } from "node:readline";
import type { JsonRpcRequest, JsonRpcResponse } from "./types.js";
import { dispatch, parseRpc, type ServerContext } from "./protocol.js";

export type LineSink = (line: string) => void;

export function processLine(context: ServerContext, line: string, sink: LineSink): void {
  const trimmed = line.trim();
  if (!trimmed) return;
  const parsed = parseRpc(trimmed);
  if (!parsed.ok) {
    const message = parsed.code === -32600 ? "Invalid Request" : "Parse error";
    const err: JsonRpcResponse = {
      jsonrpc: "2.0",
      id: null,
      error: { code: parsed.code, message, data: parsed.err },
    };
    sink(JSON.stringify(err));
    return;
  }
  const resp = dispatch(context, parsed.msg);
  if (resp) sink(JSON.stringify(resp));
}

export function replayFixture(
  context: ServerContext,
  messages: JsonRpcRequest[],
): JsonRpcResponse[] {
  const out: JsonRpcResponse[] = [];
  for (const msg of messages) {
    const reply = dispatch(context, msg);
    if (reply) out.push(reply);
  }
  return out;
}

export function serveStdio(context: ServerContext): void {
  const rl = createInterface({ input: process.stdin, terminal: false });
  const sink: LineSink = (line) => process.stdout.write(line + "\n");
  rl.on("line", (line) => {
    processLine(context, line, sink);
  });
}

export type JsonRpcRequestId = number | string;
export type JsonRpcResponseId = JsonRpcRequestId | null;

export type JsonRpcRequest = {
  jsonrpc: "2.0";
  id?: JsonRpcRequestId;
  method: string;
  params?: Record<string, unknown>;
};

export type JsonRpcError = {
  code: number;
  message: string;
  data?: unknown;
};

export type JsonRpcResponse = {
  jsonrpc: "2.0";
  id: JsonRpcResponseId;
  result?: unknown;
  error?: JsonRpcError;
};

export type JsonSchema = {
  type?: string;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  enum?: string[];
  additionalProperties?: boolean;
};

export type ToolAnnotations = {
  readOnlyHint?: boolean;
  destructiveHint?: boolean;
};

export type ToolDescriptor = {
  name: string;
  description: string;
  inputSchema: JsonSchema;
  annotations?: ToolAnnotations;
};

export type ContentBlock = { type: "text"; text: string };

export type ToolArgs = Record<string, unknown>;

export type ToolExecutor = (args: ToolArgs) => ContentBlock[];

export type Incident = {
  id: string;
  severity: "p0" | "p1" | "p2";
  title: string;
  acked: boolean;
};

import { test } from "node:test";
import { strict as assert } from "node:assert";
import {
  CLIENT_CAPABILITIES_KEY,
  CLIENT_INFO_KEY,
  dispatch,
  makeContext,
  makeRequest,
  parseRpc,
  PROTOCOL_VERSION,
  PROTOCOL_VERSION_KEY,
  SERVER_INFO_KEY,
  SERVER_NAME,
} from "../src/protocol.js";
import { TOOL_DESCRIPTORS, makeExecutors, makeIncidents } from "../src/tools.js";
import { processLine, replayFixture } from "../src/transport.js";
import type { JsonRpcRequest } from "../src/types.js";

function freshContext() {
  return makeContext(TOOL_DESCRIPTORS, makeExecutors(makeIncidents()));
}

test("server/discover returns the current contract and public cache policy", () => {
  const resp = dispatch(freshContext(), makeRequest(1, "server/discover"));
  assert.ok(resp);
  assert.equal(resp.id, 1);
  const result = resp.result as {
    resultType: string;
    supportedVersions: string[];
    capabilities: { tools: { listChanged: boolean } };
    ttlMs: number;
    cacheScope: string;
    _meta: Record<string, { name: string }>;
  };
  assert.equal(result.resultType, "complete");
  assert.deepEqual(result.supportedVersions, [PROTOCOL_VERSION]);
  assert.equal(result.capabilities.tools.listChanged, false);
  assert.equal(result.ttlMs, 3_600_000);
  assert.equal(result.cacheScope, "public");
  assert.equal(SERVER_NAME, "com.example/internal-incidents");
  assert.equal(result._meta[SERVER_INFO_KEY]?.name, SERVER_NAME);
});

test("every request requires params._meta", () => {
  const resp = dispatch(freshContext(), {
    jsonrpc: "2.0",
    id: 2,
    method: "tools/list",
    params: {},
  });
  assert.ok(resp);
  assert.equal(resp.error?.code, -32602);
});

test("every request requires client capabilities", () => {
  const resp = dispatch(freshContext(), {
    jsonrpc: "2.0",
    id: 3,
    method: "tools/list",
    params: { _meta: { [PROTOCOL_VERSION_KEY]: PROTOCOL_VERSION } },
  });
  assert.ok(resp);
  assert.equal(resp.error?.code, -32602);
});

test("unsupported versions return exact -32022 negotiation data", () => {
  const resp = dispatch(freshContext(), makeRequest(4, "tools/list", {}, "2027-01-01"));
  assert.ok(resp);
  assert.equal(resp.error?.code, -32022);
  assert.deepEqual(resp.error?.data, {
    supported: [PROTOCOL_VERSION],
    requested: "2027-01-01",
  });
});

test("missing and non-string protocol versions return -32602 without negotiation data", () => {
  const metas: Array<Record<string, unknown>> = [
    { [CLIENT_CAPABILITIES_KEY]: {} },
    { [PROTOCOL_VERSION_KEY]: 20260728, [CLIENT_CAPABILITIES_KEY]: {} },
    { [PROTOCOL_VERSION_KEY]: [PROTOCOL_VERSION], [CLIENT_CAPABILITIES_KEY]: {} },
  ];
  for (const [index, meta] of metas.entries()) {
    const resp = dispatch(freshContext(), {
      jsonrpc: "2.0",
      id: 40 + index,
      method: "tools/list",
      params: { _meta: meta },
    });
    assert.ok(resp);
    assert.equal(resp.error?.code, -32602);
    assert.equal(resp.error?.data, undefined);
  }
});

test("malformed optional clientInfo is rejected", () => {
  const resp = dispatch(freshContext(), {
    jsonrpc: "2.0",
    id: 5,
    method: "tools/list",
    params: {
      _meta: {
        [PROTOCOL_VERSION_KEY]: PROTOCOL_VERSION,
        [CLIENT_CAPABILITIES_KEY]: {},
        [CLIENT_INFO_KEY]: { name: "missing-version" },
      },
    },
  });
  assert.ok(resp);
  assert.equal(resp.error?.code, -32602);
});

test("tools/list is complete, deterministic, and cacheable", () => {
  const resp = dispatch(freshContext(), makeRequest(6, "tools/list"));
  assert.ok(resp);
  const result = resp.result as {
    resultType: string;
    tools: Array<{ name: string; inputSchema: unknown }>;
    ttlMs: number;
    cacheScope: string;
  };
  assert.equal(result.resultType, "complete");
  assert.equal(result.tools.length, 3);
  assert.deepEqual(
    result.tools.map((tool) => tool.name),
    ["incidents_ack", "incidents_get", "incidents_list"],
  );
  assert.equal(result.ttlMs, 300_000);
  assert.equal(result.cacheScope, "public");
  for (const t of result.tools) {
    assert.equal(typeof t.name, "string");
    assert.ok(t.inputSchema);
  }
});

test("tools/call dispatches to incidents_get", () => {
  const resp = dispatch(
    freshContext(),
    makeRequest(7, "tools/call", {
      name: "incidents_get",
      arguments: { id: "INC-101" },
    }),
  );
  assert.ok(resp);
  const result = resp.result as {
    resultType: string;
    isError: boolean;
    content: Array<{ text: string }>;
    _meta: Record<string, { version: string }>;
  };
  assert.equal(result.resultType, "complete");
  assert.equal(result.isError, false);
  assert.equal(result._meta[SERVER_INFO_KEY]?.version, "1.0.0");
  const text = result.content[0]?.text ?? "";
  assert.ok(text.includes("INC-101"));
});

test("tools/call unknown tool returns protocol error -32602", () => {
  const resp = dispatch(
    freshContext(),
    makeRequest(8, "tools/call", { name: "nope", arguments: {} }),
  );
  assert.ok(resp);
  assert.equal(resp.error?.code, -32602);
  assert.match(resp.error?.message ?? "", /Unknown tool/);
});

test("tools/call rejects a malformed tool name", () => {
  const resp = dispatch(
    freshContext(),
    makeRequest(9, "tools/call", { name: "", arguments: {} }),
  );
  assert.ok(resp);
  assert.equal(resp.error?.code, -32602);
});

test("known tools enforce every advertised input schema as complete tool errors", () => {
  const cases = [
    { name: "incidents_list", arguments: { severity: "p3" } },
    { name: "incidents_get", arguments: {} },
    { name: "incidents_ack", arguments: { id: 101 } },
    { name: "incidents_list", arguments: { extra: true } },
    { name: "incidents_get", arguments: [] },
  ];
  for (const [index, params] of cases.entries()) {
    const resp = dispatch(
      freshContext(),
      makeRequest(50 + index, "tools/call", params),
    );
    assert.ok(resp);
    assert.equal(resp.error, undefined);
    const result = resp.result as {
      resultType: string;
      isError: boolean;
      content: Array<{ text: string }>;
    };
    assert.equal(result.resultType, "complete");
    assert.equal(result.isError, true);
    assert.match(result.content[0]?.text ?? "", /Invalid arguments/);
  }
});

test("incidents_ack flips acked state", () => {
  const context = freshContext();
  dispatch(
    context,
    makeRequest(10, "tools/call", {
      name: "incidents_ack",
      arguments: { id: "INC-103" },
    }),
  );
  const resp = dispatch(
    context,
    makeRequest(11, "tools/call", {
      name: "incidents_get",
      arguments: { id: "INC-103" },
    }),
  );
  assert.ok(resp);
  const text = (resp.result as { content: Array<{ text: string }> }).content[0]?.text ?? "";
  assert.ok(text.includes('"acked":true'));
});

test("requests never inherit metadata from a prior call", () => {
  const context = freshContext();
  assert.ok(dispatch(context, makeRequest(12, "tools/list"))?.result);
  const missingMeta = dispatch(context, {
    jsonrpc: "2.0",
    id: 13,
    method: "tools/list",
    params: {},
  });
  assert.equal(missingMeta?.error?.code, -32602);
});

test("JSON-RPC notifications return no response", () => {
  const resp = dispatch(freshContext(), {
    jsonrpc: "2.0",
    method: "notifications/tools/list_changed",
  });
  assert.equal(resp, null);
});

test("legacy lifecycle methods are not implemented", () => {
  const initialize = dispatch(freshContext(), makeRequest(14, "initialize"));
  const shutdown = dispatch(freshContext(), makeRequest(15, "shutdown"));
  assert.equal(initialize?.error?.code, -32601);
  assert.equal(shutdown?.error?.code, -32601);
});

test("unknown modern method returns -32601", () => {
  const resp = dispatch(freshContext(), makeRequest(16, "no/such"));
  assert.ok(resp);
  assert.equal(resp.error?.code, -32601);
});

test("parseRpc rejects malformed JSON", () => {
  const r = parseRpc("not json");
  assert.equal(r.ok, false);
});

test("processLine emits -32700 envelope on parse failure", () => {
  const lines: string[] = [];
  processLine(freshContext(), "not json", (line) => lines.push(line));
  assert.equal(lines.length, 1);
  const parsed = JSON.parse(lines[0]!) as { error?: { code: number } };
  assert.equal(parsed.error?.code, -32700);
});

test("parseRpc rejects a null MCP request id", () => {
  const result = parseRpc('{"jsonrpc":"2.0","id":null,"method":"tools/list"}');
  assert.equal(result.ok, false);
  if (!result.ok) assert.equal(result.code, -32600);
});

test("replayFixture roundtrip drives only modern requests", () => {
  const msgs: JsonRpcRequest[] = [
    makeRequest(17, "server/discover"),
    makeRequest(18, "tools/list"),
    makeRequest(19, "tools/call", {
      name: "incidents_list",
      arguments: { severity: "p1" },
    }),
  ];
  const replies = replayFixture(freshContext(), msgs);
  assert.equal(replies.length, 3);
  for (const reply of replies) {
    assert.equal((reply.result as { resultType: string }).resultType, "complete");
  }
});
